"""Deterministic packaging and QA only; artwork is generated by built-in image_gen."""
from pathlib import Path
import argparse, hashlib, json, re, shutil
from PIL import Image, ImageDraw, ImageFont
ROOT=Path(__file__).parent
PROJECT=ROOT.parents[3]
ITEMS=json.loads((ROOT/'items.json').read_text(encoding='utf-8-sig'))
def sha(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def package():
    provenance=json.loads((ROOT/'generation.json').read_text(encoding='utf-8-sig'))
    (ROOT/'icons').mkdir(exist_ok=True)
    checks=[]
    brief=(PROJECT/'收藏品与整理箱图标美术需求_v2.md').read_text(encoding='utf-8-sig')
    expected={m[0]:(int(m[1]),int(m[2])) for m in re.findall(r'\| `(col_[^`]+)` \|[^\n]*?（(\d+)×(\d+)）',brief)}
    assert len(expected)==32, f'Expected 32 brief rows, got {len(expected)}'
    registry=(PROJECT/'ui/item_icons.gd').read_text(encoding='utf-8-sig')
    for item in ITEMS:
        ident=item['id']; meta=provenance[ident]
        source=Path(meta['source_path']); local=ROOT/'sources'/f'{ident}.png'
        if meta.get('initial_source_path') != str(source):
            rejected=ROOT/'sources'/'rejected';rejected.mkdir(exist_ok=True)
            shutil.copy2(meta['initial_source_path'],rejected/f'{ident}_with_background.png')
        if not local.exists(): shutil.copy2(source,local)
        im=Image.open(local).convert('RGBA'); a=im.getchannel('A')
        assert a.getextrema()[0]==0, f'{ident}: no transparent source background'
        assert a.getextrema()[1]>240, f'{ident}: missing opaque source body'
        box=a.point(lambda v:255 if v>16 else 0).getbbox()
        assert box, f'{ident}: empty art'
        im=im.crop(box)
        w,h=item['w'],item['h']; assert expected[ident]==(w,h)
        pad=2 if max(w,h)<=72 else 3
        scale=min((w-pad*2)/im.width,(h-pad*2)/im.height)
        size=(max(1,round(im.width*scale)),max(1,round(im.height*scale)))
        # Premultiplied resampling preserves generated alpha and avoids dark fringes.
        im=im.convert('RGBa').resize(size,Image.Resampling.LANCZOS).convert('RGBA')
        canvas=Image.new('RGBA',(w,h)); canvas.alpha_composite(im,((w-im.width)//2,(h-im.height)//2))
        out=ROOT/'icons'/f'{ident}.png';canvas.save(out)
        alpha=canvas.getchannel('A'); bbox=alpha.getbbox()
        assert canvas.size==expected[ident] and canvas.mode=='RGBA'
        assert bbox and bbox[0]>0 and bbox[1]>0 and bbox[2]<w and bbox[3]<h
        assert all(canvas.getpixel(p)[3]==0 for p in [(0,0),(w-1,0),(0,h-1),(w-1,h-1)])
        assert f'"{ident}"' in registry
        checks.append(dict(id=ident,name=item['name'],size=[w,h],bbox=list(bbox),transparent=True,registry_match=True,sha256=sha(out),source_sha256=sha(local),source_size=list(Image.open(local).size),status='PASS'))
    report=dict(total=32,passed=len(checks),static_status='PASS',runtime_validation='NOT_RUN',art_acceptance='PENDING_USER_REVIEW',checks=checks)
    (ROOT/'qa_report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
    previews()
    print('32/32 static checks PASS; previews generated.')
def checker(d,rect,step=16):
    x0,y0,x1,y1=rect
    for y in range(y0,y1,step):
        for x in range(x0,x1,step):
            c='#303841' if ((x-x0)//step+(y-y0)//step)%2 else '#242b33'
            d.rectangle((x,y,min(x+step-1,x1-1),min(y+step-1,y1-1)),fill=c)
def previews():
    font=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',21)
    small=ImageFont.truetype('C:/Windows/Fonts/consola.ttf',15)
    region_names=['切尔诺伯格 · 坍塌矿区','龙门城区','萨米 · 冻土林线','叙拉古 · 沃尔西尼旧城区']
    sheet=Image.new('RGB',(2560,1600),'#141b24');d=ImageDraw.Draw(sheet)
    native=Image.new('RGB',(1280,680),'#141b24');nd=ImageDraw.Draw(native)
    tiny=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',12)
    for k,item in enumerate(ITEMS):
        r,c=divmod(k,8);x,y=c*320,r*400
        if c==0:d.text((x+10,y+8),region_names[r]+'  /  4×',font=font,fill='#eeeeee')
        checker(d,(x+8,y+46,x+312,y+342))
        icon=Image.open(ROOT/'icons'/(item['id']+'.png')).convert('RGBA')
        big=icon.resize((icon.width*4,icon.height*4),Image.Resampling.NEAREST)
        sheet.paste(big,(x+160-big.width//2,y+194-big.height//2),big)
        d.text((x+12,y+348),item['name']+f"  {item['w']}×{item['h']}",font=font,fill='#ffffff')
        d.text((x+12,y+378),item['id'],font=small,fill='#b8c4d4')
        nx,ny=c*160,r*170
        checker(nd,(nx+6,ny+8,nx+154,ny+110),8)
        native.paste(icon,(nx+80-icon.width//2,ny+60-icon.height//2),icon)
        nd.text((nx+6,ny+118),item['name'],font=tiny,fill='white')
        nd.text((nx+6,ny+140),item['id'].replace('col_',''),font=tiny,fill='#b8c4d4')
    sheet.save(ROOT/'contact_sheet_4x.png');native.save(ROOT/'contact_sheet_native.png')
def deliver():
    report=json.loads((ROOT/'qa_report.json').read_text(encoding='utf-8'))
    assert report['passed']==32
    runtime=PROJECT/'art/items/runtime'
    baseline_path=ROOT/'runtime_baseline.json'
    if not baseline_path.exists():
        baseline={p.name:sha(p) for p in runtime.glob('*.png')}
        baseline_path.write_text(json.dumps(baseline,indent=2),encoding='utf-8')
    else: baseline=json.loads(baseline_path.read_text())
    for item in ITEMS:
        source=ROOT/'icons'/(item['id']+'.png');target=runtime/source.name
        if target.exists() and sha(target)!=sha(source): raise RuntimeError('Refusing to overwrite existing different asset '+str(target))
        shutil.copy2(source,target)
    targets={i['id']+'.png' for i in ITEMS}
    assert all((runtime/name).exists() and sha(runtime/name)==digest for name,digest in baseline.items() if name not in targets)
    assert all(sha(runtime/(i['id']+'.png'))==sha(ROOT/'icons'/(i['id']+'.png')) for i in ITEMS)
    report['delivery']={'runtime_count':32,'hash_match':True,'existing_unrelated_assets_preserved':True}
    (ROOT/'qa_report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
    print('Delivered 32 runtime PNGs. All hashes match; existing unrelated PNGs unchanged.')
if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--deliver',action='store_true');args=parser.parse_args()
    if args.deliver:deliver()
    else:package()
